with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , AADHAR_YN as AADHAAR_AVAILABLE_INDICATOR
        , PAN_IND_COVER_YN as PAN_PROVIDED_INDICATOR
        , cast(null as varchar) as PARTNER_IDENTIFIER
        , cast(null as varchar) as PROVIDER_REGISTRATION_NUMBER
        , cast(null as varchar) as PAN_AADHAAR_LINKED_INDICATOR
        , 'BJAZ_HG_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hg_pol_dtls') }}
    where (nullif(trim(PART_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as AADHAAR_AVAILABLE_INDICATOR
        , cast(null as varchar) as PAN_PROVIDED_INDICATOR
        , PARTNER_ID as PARTNER_IDENTIFIER
        , HOSPITAL_NO as PROVIDER_REGISTRATION_NUMBER
        , cast(null as varchar) as PAN_AADHAAR_LINKED_INDICATOR
        , 'BJAZ_HM_HOSPITAL_MASTER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__INTERMEDIARY_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as AADHAAR_AVAILABLE_INDICATOR
        , cast(null as varchar) as PAN_PROVIDED_INDICATOR
        , cast(null as varchar) as PARTNER_IDENTIFIER
        , cast(null as varchar) as PROVIDER_REGISTRATION_NUMBER
        , PAN_AADHAR_LINKED as PAN_AADHAAR_LINKED_INDICATOR
        , 'BJAZ_INTERMEDIARY' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_intermediary') }}
    where (nullif(trim(INTERMEDIARY_ID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AADHAAR_AVAILABLE_INDICATOR end) as AADHAAR_AVAILABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAN_PROVIDED_INDICATOR end) as PAN_PROVIDED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PARTNER_IDENTIFIER end) as PARTNER_IDENTIFIER,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PROVIDER_REGISTRATION_NUMBER end) as PROVIDER_REGISTRATION_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then PAN_AADHAAR_LINKED_INDICATOR end) as PAN_AADHAAR_LINKED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when AADHAAR_AVAILABLE_INDICATOR is not null or PAN_PROVIDED_INDICATOR is not null or PARTNER_IDENTIFIER is not null or PROVIDER_REGISTRATION_NUMBER is not null or PAN_AADHAAR_LINKED_INDICATOR is not null
                     then md5(upper(coalesce(cast(AADHAAR_AVAILABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(PAN_PROVIDED_INDICATOR as varchar), '') || '|' || coalesce(cast(PARTNER_IDENTIFIER as varchar), '') || '|' || coalesce(cast(PROVIDER_REGISTRATION_NUMBER as varchar), '') || '|' || coalesce(cast(PAN_AADHAAR_LINKED_INDICATOR as varchar), '')))
                end as SAT_PARTY_IDENTIFICATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_IDENTIFICATION_HASHDIFF is not null
